     "pre_process_code": "import re
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
try:
    b = config.get('body')
    if isinstance(b, dict):
        a = str(b.get('answer') or '').strip()
        if b.get('field') == 'phone_last4':
            digits = re.sub(r'\D', '', a)
            if len(digits) >= 4:
                b['answer'] = digits[-4:]
        else:
            s = a.lower()
            y, mo, dd = '', '', ''
            m = re.search(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
            if m:
                y, mo, dd = m.group(1), m.group(2), m.group(3)
            else:
                m = re.search(r'(\d{1,2})\D+(\d{1,2})\D+(\d{4})', s)
                if m:
                    dd, mo, y = m.group(1), m.group(2), m.group(3)
                else:
                    for i, nm in enumerate(MONTHS):
                        if nm[:3] in s:
                            mo = str(i + 1)
                            break
                    nums = re.findall(r'\d+', s)
                    y = next((x for x in nums if len(x) == 4), '')
                    dd = next((x for x in nums if len(x) <= 2), '')
            if y and mo and dd:
                b['answer'] = '%04d-%02d-%02d' % (int(y), int(mo), int(dd))
except Exception:
