                y, mo, dd = m.group(1), m.group(2), m.group(3)
            else:
                m = re.search(r'(\d{1,2})\D+(\d{1,2})\D+(\d{4})', s)
                if m:
                    dd, mo, y = m.group(1), m.group(2), m.group(3)
                else:
                    for i, nm in enumerate(MONTHS):
                        if nm[:3] in s:
