HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('now')

def is_bd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL

def next_bd(d):
    d = d + datetime.timedelta(days=1)
    while not is_bd(d):
        d = d + datetime.timedelta(days=1)
    return d

def add_bd(d, n):
    for _ in range(n):
        d = next_bd(d)
    return d

def last_bd_week(d):
    mon = d - datetime.timedelta(days=d.weekday())
    day = mon + datetime.timedelta(days=4)
    while day >= mon:
        if is_bd(day):
            return day
        day = day - datetime.timedelta(days=1)
    return None

def spoken(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

def money(v):
    return '{:,.2f}'.format(round(float(v), 2))

def as_list(value):
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return []
    if isinstance(value, dict):
        return [value]
    return value if isinstance(value, list) else []

def list_from_vars(vars, name, prefixes):
    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []
    if found:
        return found
    for prefix in prefixes:
        rows = dict()
        start = prefix + '.'
        for key, value in vars.items():
            if not str(key).startswith(start):
                continue
            rest = str(key)[len(start):]
            idx, _, field = rest.partition('.')
            if idx.isdigit():
                if field:
                    rows.setdefault(int(idx), dict())[field] = value
                else:
                    rows[int(idx)] = value
        if rows:
            return [rows[i] for i in sorted(rows)]
        whole = vars.get(prefix)
        if whole not in (None, ''):
            got = as_list(whole)
            if got:
                return got
    return []

try:
    now = parse_now(vars.get('now'))
    today = now.date()
    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])
    wk = last_bd_week(today)
    if wk is None or wk <= today:
        wk = last_bd_week(today + datetime.timedelta(days=7))
    lines, offers, debt, order, today_rb = [], [], [], [], []
    for it in items:
        typ = str(it.get('type') or '')
        if typ == 'credit_card':
            name = 'credit card ending ' + str(it.get('card_last4') or '')
            floor = it.get('minimum_payment')
        elif typ == 'car_loan':
            name = 'car loan'
            floor = it.get('instalment_amount')
        else:
            name = 'personal loan'
            floor = it.get('instalment_amount')
        due = float(it.get('past_due') or 0)
        floor = float(floor or 0)
        days = int(float(it.get('days_late') or 0))
        late = days >= 8
        deadline = add_bd(today, 7 if late else 12)
        a1 = wk if (wk is not None and wk <= deadline) else deadline
        attempts = 2 if late else 1
        ref = str(it.get('product_id') or '')
        order.append(ref)
        debt.append('Your ' + name + ' has ' + money(due) + ' past due and is ' + str(days) + ' days late.')
        today_rb.append('your ' + name + ', ' + money(due) + ' today, ' + spoken(today))
        steps = ['For your ' + name + ', can you pay the full ' + money(due) + ' by ' + spoken(a1) + '?']
        if attempts == 2:
            steps.append('For your ' + name + ', can you pay ' + money(floor) + ' by ' + spoken(deadline) + '? The rest stays overdue.')
        offers.append(dict(ref=ref, name=name, steps=steps, deadline=deadline.isoformat(), floor=floor, due=due))
        lines.append('- ' + name + ' (product_id ' + ref + '): past due ' + money(due) + ', ' + str(days) + ' days late, ' + ('late' if late else 'early') + ' band. Floor (lowest amount allowed): ' + money(floor) + '. Any amount from ' + money(floor) + ' to ' + money(due) + ' is accepted. Deadline (latest date): ' + spoken(deadline) + ' (' + deadline.isoformat() + '). Persuasion attempts: ' + str(attempts) + '. If the full amount is too much, say exactly: I can offer ' + money(floor) + ' by ' + spoken(a1) + ' instead. The rest stays overdue. If a date after the deadline is asked, say exactly: The latest date I can record is ' + spoken(deadline) + '. Can you pay on ' + spoken(deadline) + '? (a no to this is a flat refusal). If a vague period is given, ask once: Which exact day? If still none, propose ' + spoken(deadline) + '. If the amount is below the floor, say exactly: I cannot record an amount below ' + money(floor) + '. Can you pay ' + money(floor) + '?')
    table = []
    for i in range(0, 22):
        d = today + datetime.timedelta(days=i)
        if is_bd(d):
            table.append(spoken(d) + ' = ' + d.isoformat() + ': business day')
        else:
            nb = next_bd(d)
            table.append(spoken(d) + ' = ' + d.isoformat() + ': NOT a business day, offer ' + spoken(nb) + ' (' + nb.isoformat() + ') instead')
    mon = today - datetime.timedelta(days=today.weekday())
    wd = []
    for i in range(7):
        wd.append('this ' + WEEKDAYS[i].title() + ' = ' + (mon + datetime.timedelta(days=i)).isoformat() + ', next ' + WEEKDAYS[i].title() + ' = ' + (mon + datetime.timedelta(days=7 + i)).isoformat())
    n = len(offers)
    ask = 'Can you make this payment today?' if n == 1 else 'Can you pay all of them today?'
    vars['debt_text'] = 'Thank you. I am calling from the collections team about a late payment. ' + ' '.join(debt) + ' ' + ask
    vars['today_readback'] = 'To confirm: ' + '; '.join(today_rb) + '. Do you confirm?'
    vars['facts_text'] = 'Today is ' + spoken(today) + ' (' + today.isoformat() + '). Products, in this order:\n' + '\n'.join(lines) + '\nA promise date must be today or later, a business day, and not after that product\'s deadline. Calendar:\n' + '\n'.join(table) + '\nWeekday words: ' + '; '.join(wd) + '.\nIf the customer pays today, read back: ' + vars['today_readback']
    vars['offers_json'] = json.dumps(offers)
    vars['product_order'] = json.dumps(order)
    vars['product_count'] = str(max(n, 1))
    vars['offer_item'] = '0'
    vars['offer_step'] = '-1'
    vars['offer_answer'] = 'stay'
    vars['agreed_json'] = '[]'
    vars['facts_state'] = 'ok' if n else 'empty'
    if n:
        vars['close_outcome'] = 'no_promise'
        vars['close_reason'] = 'refused'
except Exception:
    vars['debt_text'] = 'Thank you. I am calling from the collections team about a late payment. Can you make this payment today?'
    vars['facts_text'] = 'The account details could not be read. Say you do not have that information.'
    vars['offers_json'] = '[]'
    vars['product_order'] = '[]'
    vars['today_readback'] = ''
    vars['facts_state'] = 'error'
