    if isinstance(b, dict):
        if b.get('amount') not in (None, ''):
            b['amount'] = round(float(str(b['amount']).replace(',', '')), 2)
        ref = str(b.get('product_id') or '')
        try:
            o = next((x for x in json.loads(vars.get('offers_json') or '[]') if x.get('ref') == ref), None)
            today = datetime.date.fromisoformat(str(vars.get('now'))[:10])
            d = datetime.date.fromisoformat(str(b.get('date'))[:10])
            if d < today:
                d = today
            while d.weekday() > 4 or d.isoformat() in HOL:
                d = d + datetime.timedelta(days=1)
            if o:
                dl = datetime.date.fromisoformat(o['deadline'])
                if d > dl:
                    d = dl
                b['amount'] = round(min(max(float(b['amount']), float(o['floor'])), float(o['due'])), 2)
            b['date'] = d.isoformat()
        except Exception:
            pass
        q = json.loads(vars.get('cp_queue') or '[]')
        q.append(ref)
        vars['cp_queue'] = json.dumps(q)
except Exception:
    pass
