HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('now')

def is_bd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL

def next_bd(d):
    d = d + datetime.timedelta(days=1)
    while not is_bd(d):
        d = d + datetime.timedelta(days=1)
    return d

def add_bd(d, n):
    for _ in range(n):
        d = next_bd(d)
    return d

def last_bd_week(d):
    mon = d - datetime.timedelta(days=d.weekday())
    day = mon + datetime.timedelta(days=4)
    while day >= mon:
        if is_bd(day):
            return day
        day = day - datetime.timedelta(days=1)
    return None

def spoken(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

def money(v):
    return '{:,.2f}'.format(round(float(v), 2))

def as_list(value):
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
