    nxt = next_bd(today)
    parts = []
    if hhmm < '19:00':
        start = 'from 10:00' if hhmm < '10:00' else 'later than ' + hhmm
        parts.append('today, ' + spoken(today) + ' (' + today.isoformat() + '), ' + start + ' until 19:00')
    parts.append(spoken(nxt) + ' (' + nxt.isoformat() + '), from 10:00 to 19:00')
    vars['callback_window_text'] = 'It is now ' + spoken(today) + ', ' + hhmm + '. A callback can only be booked ' + ' or on '.join(parts) + ', both ends included. Any other day or time is outside the window.'
except Exception:
    vars['callback_window_text'] = 'A callback can be booked on the next business day from 10:00 to 19:00.'
