                    nums = re.findall(r'\d+', s)
                    y = next((x for x in nums if len(x) == 4), '')
                    dd = next((x for x in nums if len(x) <= 2), '')
            if y and mo and dd:
                b['answer'] = '%04d-%02d-%02d' % (int(y), int(mo), int(dd))
except Exception:
