    if ans == 'agreed' and item < len(offers):
        amt = str(vars.get('agreed_amount') or '')
        try:
            amt = '{:,.2f}'.format(min(max(float(amt.replace(',', '')), float(offers[item].get('floor') or 0)), float(offers[item].get('due') or 0)))
        except Exception:
            pass
        agreed.append(dict(ref=offers[item]['ref'], name=offers[item]['name'], deadline=offers[item]['deadline'], amount=amt, date=str(vars.get('agreed_date') or '')))
        item, step = item + 1, 0
    elif ans in ('noted', 'recorded'):
        item, step = item + 1, 0
    else:
        step += 1
    handled = set(json.loads(vars.get('promised_json') or '[]')) | set(json.loads(vars.get('notes_json') or '[]'))
    while item < len(offers) and offers[item]['ref'] in handled:
