            for a in agreed:
                try:
                    dt = datetime.date.fromisoformat(a['date'][:10])
                    dl = datetime.date.fromisoformat(a['deadline'])
                    today = datetime.date.fromisoformat(str(vars.get('now'))[:10])
                    if dt < today:
