                    while dt.weekday() > 4 or dt.isoformat() in ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']:
                        dt = dt + datetime.timedelta(days=1)
                    if dt > dl:
                        parts.append('your ' + a['name'] + ', ' + a['amount'] + ' on ' + spoken(dl) + ', which is the latest date I can record for it (' + dl.isoformat() + ')')
                    else:
                        parts.append('your ' + a['name'] + ', ' + a['amount'] + ' on ' + spoken(dt) + ' (' + dt.isoformat() + ')')
                except Exception:
                    parts.append('your ' + a['name'] + ', ' + a['amount'] + ' on ' + a['date'])
            vars['readback_text'] = 'To confirm: ' + '; '.join(parts) + '. Do you confirm?'
            vars['offer_state'] = 'confirm'
        else:
            vars['offer_state'] = 'done'
    elif step >= len(offers[item]['steps']):
        vars['offer_state'] = 'out_of_attempts'
        vars['note_ref'] = offers[item]['ref']
        vars['note_name'] = offers[item]['name']
    else:
        vars['offer_state'] = 'offer'
